#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[])
{
    const char *input = (argc >= 2) ? argv[1] : "";
    size_t len = strlen(input);
    char *stack = malloc(len + 1);
    if (!stack) { perror("malloc"); return 1; }
    size_t sp = 0;
    int balanced = 1;
    for (size_t i = 0; i < len && balanced; ++i) {
        char c = input[i];
        switch (c) {
            case '(':
            case '[':
            case '{':
                stack[sp++] = c; break;
            case ')':
                if (sp == 0 || stack[sp-1] != '(') balanced = 0; else --sp; break;
            case ']':
                if (sp == 0 || stack[sp-1] != '[') balanced = 0; else --sp; break;
            case '}':
                if (sp == 0 || stack[sp-1] != '{') balanced = 0; else --sp; break;
            default:
                balanced = 0; break;
        }
    }
    if (sp != 0) balanced = 0;
    puts(balanced ? "BALANCED" : "UNBALANCED");
    free(stack);
    return 0;
}
